import json
from pathlib import Path
base='http://localhost:5080/api/v1'

def item(name, method, path, expected, test, body=None, headers=None, pre=None):
    req={'method':method,'header':[{'key':k,'value':v} for k,v in (headers or [])], 'url':path if path.startswith('http') else base+path}
    if body is not None:
        raw=body if isinstance(body,str) else json.dumps(body,separators=(',',':'))
        req['body']={'mode':'raw','raw':raw,'options':{'raw':{'language':'json'}}}
        req['header'].append({'key':'Content-Type','value':'application/json'})
    events=[]
    if pre: events.append({'listen':'prerequest','script':{'type':'text/javascript','exec':pre.splitlines()}})
    events.append({'listen':'test','script':{'type':'text/javascript','exec':test.splitlines()}})
    return {'name':name,'request':req,'event':events}

