 item('SRCH-07 First page of seeded trips','GET','/trips?origin=Seed%20Origin%20Station&destination=Seed%20Destination%20Station&departureDate=2026-12-01&passengerCount=1&page=0&size=1',200,"pm.test('First page metadata and item count',()=>{pm.response.to.have.status(200);const b=pm.response.json();pm.expect(b.page).to.eql(0);pm.expect(b.size).to.eql(1);pm.expect(b.items.length).to.be.at.most(1);pm.environment.set('firstPageIds',JSON.stringify(b.items.map(x=>x.id)));pm.environment.set('firstPageTotal',b.totalElements)});"),
