 item('BOOK-22 List own bookings','GET','/bookings',200,"pm.test('Authenticated bookings list returns 200',()=>pm.response.to.have.status(200)); pm.test('List only contains own bookings with valid statuses',()=>{const b=pm.response.json();pm.expect(b.items).to.be.an('array');pm.expect(b).to.have.property('totalElements');pm.expect(b.items.every(x=>x.customerId==='01990a00-0000-7000-8000-000000000002'&&['PENDING_PAYMENT','CONFIRMED','PAID','EXPIRED','CANCELLED','REFUND_PENDING','REFUNDED','COMPLETED'].includes(x.status))).to.eql(true);pm.environment.set('seedBookingId',b.items[0].id);const payLater=b.items.find(x=>x.paymentChannel==='PAY_LATER'&&x.status==='CONFIRMED');if(payLater)pm.environment.set('payLaterBookingId',payLater.id);const pending=b.items.find(x=>x.paymentChannel==='PREPAID'&&x.status==='PENDING_PAYMENT');if(pending)pm.environment.set('pendingBookingId',pending.id)});",headers=[('Authorization','Bearer {{accessToken}}')]),
